const fs = require('fs');

function parseRSS(file, site) {
  try {
    const data = fs.readFileSync(file, 'utf8');
    const regex = /<(item|entry)>([\s\S]*?)<\/\1>/g;
    let match;
    let count = 0;
    while ((match = regex.exec(data))) {
      const itemContent = match[2];

      let title = '';
      const titleMatch = itemContent.match(/<title[^>]*>([\s\S]*?)<\/title>/);
      if (titleMatch) {
        title = titleMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
      }

      let link = '';
      const linkMatch = itemContent.match(/<link[^>]*>([\s\S]*?)<\/link>/);
      if (linkMatch) {
        link = linkMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
      } else {
        // Try <link href="..."/> style for atom feeds
        const hrefMatch = itemContent.match(/<link[^>]+href=["']([^"']+)["']/);
        if (hrefMatch) link = hrefMatch[1].trim();
      }

      let pubDate = '';
      const pubDateMatch = itemContent.match(/<(pubDate|published|updated)>([\s\S]*?)<\/\1>/);
      if (pubDateMatch) {
        pubDate = pubDateMatch[2].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
      }

      let desc = '';
      const descMatch = itemContent.match(/<(description|summary)>([\s\S]*?)<\/\1>/);
      if (descMatch) {
        desc = descMatch[2].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
      }

      console.log(JSON.stringify({ site, title, link, pubDate, desc }));
      count++;
    }
  } catch(e) {
    console.error(`Error parsing ${file}: ${e.message}`);
  }
}

const args = process.argv.slice(2);
if (args.length >= 2) {
  parseRSS(args[0], args[1]);
} else {
  console.log("Usage: node parse_any_rss.js <file> <site_name>");
}

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const OUTDIR = '/tmp/scout_feeds';
const files = [
  { name: 'CoinDesk', file: 'coindesk.xml' },
  { name: 'CoinTelegraph', file: 'cointelegraph.xml' },
  { name: 'Decrypt', file: 'decrypt.xml' },
  { name: 'Google News', file: 'googlenews.xml' },
  { name: 'BeInCrypto', file: 'beincrypto.xml' },
  { name: 'The Block', file: 'theblock.xml' },
  { name: 'CryptoSlate', file: 'cryptoslate.xml' },
  { name: 'CryptoFox Markets', file: 'cryptofox_markets.xml' },
  { name: 'CryptoFox Regulation', file: 'cryptofox_regulation.xml' }
];

function cleanString(str) {
  if (!str) return '';
  return str
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]*>/g, '')
    .trim();
}

const parsedItems = [];

for (const entry of files) {
  const filePath = path.join(OUTDIR, entry.file);
  if (!fs.existsSync(filePath)) continue;

  const content = fs.readFileSync(filePath, 'utf8');

  // Use a regex to extract item or entry nodes
  const regex = /<(item|entry)>([\s\S]*?)<\/\1>/g;
  let match;
  while ((match = regex.exec(content))) {
    const itemContent = match[2];

    let title = '';
    const titleMatch = itemContent.match(/<title[^>]*>([\s\S]*?)<\/title>/);
    if (titleMatch) title = cleanString(titleMatch[1]);

    let link = '';
    const linkMatch = itemContent.match(/<link[^>]*>([\s\S]*?)<\/link>/);
    if (linkMatch) {
      link = cleanString(linkMatch[1]);
    } else {
      const hrefMatch = itemContent.match(/<link[^>]+href=["']([^"']+)["']/);
      if (hrefMatch) link = cleanString(hrefMatch[1]);
    }

    let pubDate = '';
    const pubDateMatch = itemContent.match(/<(pubDate|published|updated)>([\s\S]*?)<\/\1>/);
    if (pubDateMatch) pubDate = cleanString(pubDateMatch[2]);

    let desc = '';
    const descMatch = itemContent.match(/<(description|summary)>([\s\S]*?)<\/\1>/);
    if (descMatch) desc = cleanString(descMatch[2]);

    parsedItems.push({
      site: entry.name,
      title,
      link,
      pubDate,
      desc
    });
  }
}

// Write parsed items to a JSON file
fs.writeFileSync('/tmp/scout_feeds/parsed.json', JSON.stringify(parsedItems, null, 2));
console.log(`Parsed ${parsedItems.length} items from RSS feeds.`);

const fs = require('fs');

const items = JSON.parse(fs.readFileSync('/tmp/scout_feeds/parsed.json', 'utf8'));

// Filter items within last 24-48 hours. Let's see some example pubDates first to understand the format.
console.log("Sample pubDates:");
for (let i = 0; i < Math.min(items.length, 10); i++) {
  console.log(`${items[i].site}: "${items[i].pubDate}" -> "${items[i].title}"`);
}

