filtered.filter(item => {
  const text = (item.title + " " + item.desc).toLowerCase();
  return text.includes("mt. gox") || text.includes("mt gox") || text.includes("gox");
}).forEach(item => {
  console.log(`[${item.site}] ${item.title}\n  URL: ${item.link}\n`);
